var n=`0177-minestrone`;var i=`world-0177`;var a=`IT`;var o=`southern-europe`;var s=4;var r=42;var g={en:`Minestrone`,ua:`Мінестроне`};var l={en:`A classic dish from Italy, featuring yellow onion, carrot, celery stalk, potato. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Італія. Основні складники: жовта цибуля, морква, стебло селери, картопля. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var d=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`yellow-onion`,150,`g`],[`carrot`,150,`g`],[`celery-stalk`,120,`g`],[`extra-virgin-olive-oil`,35,`ml`]]},{en:`Add the listed ingredients to the pot. Keep at a gentle simmer for about 30 minutes, until tender and cooked through.`,ua:`Додайте зазначені складники до каструлі. Варіть за слабкого кипіння приблизно 30 хвилин до м’якості та готовності.`,t:[`simmering`],m:30,i:[[`potato`,230,`g`],[`zucchini`,250,`g`],[`white-cabbage`,170,`g`],[`green-beans`,200,`g`],[`canned-kidney-beans`,280,`g`],[`vegetable-stock`,1200,`ml`],[`tomato`,200,`g`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:3,i:[[`basil`,20,`g`],[`parmigiano-reggiano`,50,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]}];var u={slug:n,id:i,country:`IT`,region:o,servings:4,minutes:42,title:g,text:l,steps:d};export{a as country,u as default,i as id,r as minutes,o as region,s as servings,n as slug,d as steps,l as text,g as title};